12	// some nodes' new records durably saved and others not yet saved. The command
13	// must report the failure with new=0 duplicate=0 (it must not present the
14	// already-persisted part as a successful batch), and resubmitting the very
15	// same JSON verbatim after the fault is cleared must converge: saved records
16	// count as duplicates, the one record still missing is added exactly once,
17	// and the batch-internal repeat still counts as a duplicate.
18	//
19	// The fault is injected only at the persistence boundary (writeNodeFile),
20	// after all validation and merging has run, so the exercise goes through the
21	// real code path — real atomic file writes, real on-disk state afterwards —
22	// without filling a disk or relying on wall-clock timing. The same two nodes
23	// run under both failure positions, so the result cannot depend on which node
24	// happens to be written first (that order is deliberately not promised).
25	
26	// persistFault temporarily replaces writeNodeFile. failOnCall is the
27	// 1-based number of the node-file write that must return an error; every
28	// other write performs the real atomic persistence. It returns a pointer to
29	// the number of writes actually attempted.
30	func persistFault(t *testing.T, failOnCall int) *int {
31		t.Helper()
32		calls := 0
33		orig := writeNodeFile
34		writeNodeFile = func(path string, records []Heartbeat) error {
35			calls++
36			if calls == failOnCall {
37				return errors.New("injected persistence failure")
38			}
39			return orig(path, records)
40		}
41		t.Cleanup(func() { writeNodeFile = orig })
42		return &calls
43	}
44	
45	// assertHistory loads a node's history through the normal query interface on
46	// a freshly opened store (so the assertion is against data durably on disk,
47	// not in-memory state) and checks the records exactly.
48	func assertHistory(t *testing.T, dir, node string, want []Heartbeat) {
49		t.Helper()
50		store, err := OpenStore(dir)
51		if err != nil {
52			t.Fatal(err)
53		}
54		got, err := store.History(node)
55		if err != nil {
56			t.Fatalf("history for %q after failure must be readable: %v", node, err)
57		}
58		if len(got) != len(want) {
59			t.Fatalf("node %q history has %d records, want %d: %+v", node, len(got), len(want), got)
60		}
61		for i := range want {
62			if !got[i].Equal(want[i]) {
63				t.Errorf("node %q record %d = %+v, want %+v", node, i, got[i], want[i])
64			}
65		}
66		// History must be ascending by seq with no duplicate seq.
67		for i := 1; i < len(got); i++ {
68			if got[i-1].Seq >= got[i].Seq {
69				t.Errorf("node %q history not strictly ascending: %+v", node, got)
70			}
71		}
72	}
73	
74	// TestSubmitPartialPersistFailureThenVerbatimResubmit drives the full
75	// sequence: partial save during a failed submit, verification through history
76	// of exactly what landed, then a verbatim resubmit that converges to
77	// new=1 duplicate=3 with no record replaced or lost.
78	func TestSubmitPartialPersistFailureThenVerbatimResubmit(t *testing.T) {
79		dir := t.TempDir()
80		store, err := OpenStore(dir)
81		if err != nil {
82			t.Fatal(err)
83		}
84		receive := testBase
85	
86		// Fixed instants: both nodes already have seq 1 before the batch.
87		alpha1 := hb("alpha", 1, receive.Add(-2*time.Minute), "1.0", 100, 0)
88		beta1 := hb("beta", 1, receive.Add(-2*time.Minute), "1.0", 200, 0)
89		if _, _, err := store.Submit([]Heartbeat{alpha1, beta1}, receive); err != nil {
90			t.Fatal(err)
91		}
92	
93		// The batch adds seq 2 to both nodes. One node's seq 2 is present twice
94		// with identical content, and one existing seq 1 is carried along: four
95		// input records in total, all legal.
96		alpha2 := hb("alpha", 2, receive.Add(-time.Minute), "1.0", 101, 0)
97		beta2 := hb("beta", 2, receive.Add(-time.Minute), "1.0", 201, 1)
98		batch := []Heartbeat{alpha2, alpha2, beta2, beta1}
99	
100		// Fail the SECOND node-file write. Both nodes gain a record, so exactly
101		// one real write completes and durably renames a file into place before
102		// the failing one: this is a genuine partial save, not an error returned
103		// before anything was persisted.
104		calls := persistFault(t, 2)
105		newC, dupC, err := store.Submit(batch, receive)
106		if err == nil {
107			t.Fatal("submit must report a failure when a node-file write fails midway")
108		}
109		if !strings.Contains(err.Error(), "failed to persist heartbeat batch") {
110			t.Fatalf("error must be the persistence failure, got: %v", err)
111		}
112		if newC != 0 || dupC != 0 {
113			t.Errorf("failed submit must report new=0 duplicate=0, got new=%d duplicate=%d (the already-saved part must not be reported as success)", newC, dupC)
114		}
115		if *calls != 2 {
116			t.Fatalf("test setup: expected two node-file writes (one success, one failure), got %d; a failure that saved no new record is a different scenario", *calls)
117		}
118	
119		// Observe the real, on-disk outcome through the history query interface.
120		// Which node was persisted first is not promised and varies with map
121		// iteration, so identify the persisted node from the data instead of
122		// naming it. Exactly one node must have gained seq 2.
123		query, err := OpenStore(dir)
124		if err != nil {
125			t.Fatal(err)
126		}
127		alphaHist, err := query.History("alpha")
128		if err != nil {
129			t.Fatal(err)
130		}
131		betaHist, err := query.History("beta")
132		if err != nil {
133			t.Fatal(err)
134		}
135		var persistedNode, missingNode string
136		switch {
137		case len(alphaHist) == 2 && len(betaHist) == 1:
138			persistedNode, missingNode = "alpha", "beta"
139		case len(alphaHist) == 1 && len(betaHist) == 2:
140			persistedNode, missingNode = "beta", "alpha"
141		default:
142			t.Fatalf("after the partial failure exactly one node must have 2 records and the other 1, got alpha=%d beta=%d", len(alphaHist), len(betaHist))
143		}
144		t.Logf("partial save: node %q persisted seq 2 first; node %q did not", persistedNode, missingNode)
145	
146		// The node that wrote first has its original seq 1 intact plus the new
147		// seq 2 with the submitted content; the other node has only its seq 1.
148		wantPersisted := []Heartbeat{alpha1, alpha2}
149		wantMissing := []Heartbeat{beta1}
150		if persistedNode == "beta" {
151			wantPersisted = []Heartbeat{beta1, beta2}
152			wantMissing = []Heartbeat{alpha1}
153		}
154		assertHistory(t, dir, persistedNode, wantPersisted)
155		assertHistory(t, dir, missingNode, wantMissing)
156	
157		// Clear the fault and resubmit the SAME four records verbatim, reusing
158		// the original legal receive time — duplicate detection must not be
159		// dodged by altering content or timestamps.
160		newC, dupC, err = store.Submit(batch, receive)
161		if err != nil {
162			t.Fatalf("verbatim resubmit after the fault is cleared must succeed: %v", err)
163		}
164		if newC != 1 || dupC != 3 {
165			t.Errorf("resubmit: new=%d duplicate=%d, want new=1 duplicate=3 (the landed record is a duplicate, the missing one is added once, and the in-batch repeat is a duplicate)", newC, dupC)
166		}
167	
168		// Final state: both nodes end with exactly seq 1 and seq 2, ascending,
169		// and same seq numbers across the two nodes stay independent records.
170		// Neither the old seq-1 content nor the new seq-2 content was replaced
171		// or lost.
172		assertHistory(t, dir, "alpha", []Heartbeat{alpha1, alpha2})
173		assertHistory(t, dir, "beta", []Heartbeat{beta1, beta2})
174	}
175	
176	// TestSubmitPersistenceFailureBeforeAnyNewSaveLeavesNothingNew is the
177	// contrasting case: a write failure on the FIRST node-file write, before any
178	// new record has been persisted. It must not be mistaken for the partial-save
179	// recovery scenario — no node gains anything, and the subsequent resubmit
180	// adds both nodes' new records.
181	func TestSubmitPersistenceFailureBeforeAnyNewSaveLeavesNothingNew(t *testing.T) {
182		dir := t.TempDir()
183		store, err := OpenStore(dir)
184		if err != nil {
185			t.Fatal(err)
186		}
187		receive := testBase
188	
189		alpha1 := hb("alpha", 1, receive.Add(-2*time.Minute), "1.0", 100, 0)
190		beta1 := hb("beta", 1, receive.Add(-2*time.Minute), "1.0", 200, 0)
191		if _, _, err := store.Submit([]Heartbeat{alpha1, beta1}, receive); err != nil {
192			t.Fatal(err)
193		}
194	
195		alpha2 := hb("alpha", 2, receive.Add(-time.Minute), "1.0", 101, 0)
196		beta2 := hb("beta", 2, receive.Add(-time.Minute), "1.0", 201, 1)
197		batch := []Heartbeat{alpha2, alpha2, beta2, beta1}
