201		if err == nil {
202			t.Fatal("expected a persistence failure")
203		}
204		if !strings.Contains(err.Error(), "failed to persist heartbeat batch") {
205			t.Fatalf("wrong error: %v", err)
206		}
207		if newC != 0 || dupC != 0 {
208			t.Errorf("failed submit must report new=0 duplicate=0, got new=%d duplicate=%d", newC, dupC)
209		}
210		if *calls != 1 {
