214		// No new record landed for either node; both seq-1 records are intact.
215		assertHistory(t, dir, "alpha", []Heartbeat{alpha1})
216		assertHistory(t, dir, "beta", []Heartbeat{beta1})
217	
218		// After clearing the fault, the verbatim batch adds both seq-2 records:
219		// two new, two duplicates (one in-batch repeat, one existing seq 1).
220		newC, dupC, err = store.Submit(batch, receive)
221		if err != nil {
222			t.Fatalf("resubmit must succeed: %v", err)
223		}
224		if newC != 2 || dupC != 2 {
225			t.Errorf("resubmit: new=%d duplicate=%d, want new=2 duplicate=2", newC, dupC)
226		}
