558				if _, err := reopenStore(t, dir).History(tc.victim); err == nil || !IsCorrupt(err) {
559					t.Fatalf("history on the misowned location must keep refusing, got %v", err)
560				}
561			})
562		}
563	}
564	
565	// fmtNode renders a node id the way store error messages quote it.
566	func fmtNode(node string) string {
567		return `"` + node + `"`
568	}
569

