1	package main
2	
3	// End-to-end regression tests for "a node whose batch records are all already
4	// saved does not have its file re-saved", exercised through the real
5	// `heartbeat submit` command in a re-executed process.
6	//
7	// The package-level tests watch the persistence seam directly. From the
8	// command boundary that seam is unreachable, so these tests create the real
9	// outage a redundant rewrite would hit — deterministically, offline and with
10	// no file-time waiting:
11	//
12	//   - Short ids persist under <data>/nodes and long ids under <data>/slots.
13	//     Making one of those directories read-only still allows the directory
14	//     lock (held on <data>/lock) to be taken and saved history to be read, but
15	//     makes an atomic node-file replacement fail at temp-file creation.
16	//   - A control submit that genuinely needs a write under that condition is
17	//     asserted to FAIL, proving the fault really blocks writes in this setup.
18	//     Therefore an all-duplicate submit that SUCCEeds proves no rewrite was
19	//     attempted — byte-identical files alone could not show that.
20	//   - The two directories let a mixed batch scope the fault per node: a
21	//     duplicate-only short node (nodes/ read-only) must not block a genuine
22	//     new record for a long node writing into the writable slots/, and the
23	//     reverse layout behaves the same.
24	//
25	// Identity/content rules are unchanged: equivalent timezone and JSON-escape
26	// spellings still count as duplicates with occurrence-based counts, while the
27	// original stored text is preserved.
28	
29	import (
30		"os"
31		"path/filepath"
32		"strings"
33		"testing"
34	)
35	
36	// readonlyDir chmods a directory read-only (and executable, so files in it can
37	// still be opened and read) and restores it before the temp directory is
38	// removed. It is not skipped when the tests happen to run as root: under root
39	// permission bits do not block writes, in which case the caller's control
40	// assertion fails first and reports the environment rather than passing
41	// vacuously.
42	func readonlyDir(t *testing.T, dir string) {
43		t.Helper()
44		if err := os.Chmod(dir, 0o500); err != nil {
45			t.Fatalf("chmod %s read-only: %v", dir, err)
46		}
47		t.Cleanup(func() {
48			if err := os.Chmod(dir, 0o755); err != nil {
49				t.Errorf("restore %s permissions: %v", dir, err)
50			}
51		})
52	}
53	
54	// assertNoTempFiles fails if an atomic-write temp file was left (or ever
55	// created) in dir: a skipped rewrite must not leave .tmp-* residue.
56	func assertNoTempFiles(t *testing.T, dir string) {
57		t.Helper()
58		entries, err := os.ReadDir(dir)
59		if err != nil {
60			t.Fatalf("read %s: %v", dir, err)
61		}
62		for _, e := range entries {
63			if strings.HasPrefix(e.Name(), ".tmp-") {
64				t.Errorf("a skipped rewrite must not create temp files, found %s in %s", e.Name(), dir)
65			}
66		}
67	}
68	
69	// TestCLIDuplicateOnlySubmitSucceedsWhenNodesDirCannotRewrite covers the
70	// short-id layout: reconnect retransmits already-saved records while the
71	// nodes directory cannot accept a replacement file. The submit must still
72	// succeed (new=0, duplicates counted per input occurrence), history must gain
73	// no row and the file must be byte-identical. A control new-record submit
74	// proves the read-only directory really does block a needed write.
75	func TestCLIDuplicateOnlySubmitSucceedsWhenNodesDirCannotRewrite(t *testing.T) {
76		dir := t.TempDir()
77		submitBatch(t, dir, `[
78		  {"node":"dup","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":12345,"missed":0},
79		  {"node":"dup","seq":2,"collected_at":"2026-10-01T11:59:30Z","version":"1.26.0","height":12350,"missed":0}
80		]`)
81		before := readNodeFile(t, dir, "dup")
82		nodesDir := filepath.Join(dir, "nodes")
83		readonlyDir(t, nodesDir)
84	
85		// Control: a genuinely new seq cannot be persisted while nodes/ is
86		// read-only. This pins the fault: if it did not fail, the success below
87		// would prove nothing about whether a rewrite happened.
88		out, errOut, code := runCLI(t, dir, `[
89		  {"node":"dup","seq":3,"collected_at":"2026-10-01T11:59:45Z","version":"1.26.0","height":12355,"missed":0}
90		]`, "heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
91		if code == 0 {
92			t.Fatalf("control: a needed write must fail with nodes/ read-only; stdout=%q", out)
93		}
94		if !strings.Contains(errOut, "failed to persist heartbeat batch") {
95			t.Fatalf("control failure should be a persistence error, got stderr=%q (running as root makes permission bits ineffective)", errOut)
96		}
97	
98		// The reconnect batch: seq 1 retransmitted twice (once with an equivalent
99		// timezone spelling) and seq 2 once — three input occurrences, all saved.
100		out, errOut, code = runCLI(t, dir, `[
101		  {"node":"dup","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":12345,"missed":0},
102		  {"node":"dup","seq":1,"collected_at":"2026-10-01T19:59:00+08:00","version":"1.26.0","height":12345,"missed":0},
103		  {"node":"dup","seq":2,"collected_at":"2026-10-01T11:59:30Z","version":"1.26.0","height":12350,"missed":0}
104		]`, "heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
105		if code != 0 {
106			t.Fatalf("an all-duplicate submit must succeed without rewriting: exit=%d stderr=%q", code, errOut)
107		}
108		if strings.TrimRight(out, "\n") != "submitted: new=0 duplicate=3" {
109			t.Errorf("stdout=%q, want new=0 duplicate=3", out)
110		}
111	
112		// No temp file was ever created in the read-only directory.
113		assertNoTempFiles(t, nodesDir)
114	
115		// Restore permissions for the byte snapshot helper, then verify the file
116		// is unchanged and history has exactly the original two rows in order.
117		if err := os.Chmod(nodesDir, 0o755); err != nil {
118			t.Fatal(err)
119		}
120		if got := readNodeFile(t, dir, "dup"); got != before {
121			t.Errorf("duplicate-only node file was rewritten:\nbefore=%q\nafter =%q", before, got)
122		}
123		lines := historyLines(t, dir, "dup")
124		if len(lines) != 2 ||
125			lines[0] != "node=dup seq=1 collected_at=2026-10-01T11:59:00Z version=1.26.0 height=12345 missed=0" ||
126			lines[1] != "node=dup seq=2 collected_at=2026-10-01T11:59:30Z version=1.26.0 height=12350 missed=0" {
127			t.Errorf("history gained or altered rows: %q", lines)
128		}
129	}
130	
131	// TestCLIDuplicateOnlyLongIDSubmitSucceedsWhenSlotsDirCannotRewrite is the
132	// same guarantee for the slots/ layout: a long id must not be treated as a
133	// new node, and its duplicate-only resubmit must not attempt a slot rewrite.
134	func TestCLIDuplicateOnlyLongIDSubmitSucceedsWhenSlotsDirCannotRewrite(t *testing.T) {
135		dir := t.TempDir()
136		// "long-node-" is 10 bytes; 13 repeats = 130 bytes, past the 125-byte
137		// legacy-name limit, so the id uses the slots/ layout.
138		longNode := strings.Repeat("long-node-", 13)
139		submitBatch(t, dir, longIDJSON(longNode, 1, 12345, 0, "1.26.0", "2026-10-01T11:59:00Z"))
140		slotPath := nodeFileHexPath(dir, longNode)
141		beforeBytes, err := os.ReadFile(slotPath)
142		if err != nil {
143			t.Fatal(err)
144		}
145		slotsDir := filepath.Join(dir, "slots")
146		readonlyDir(t, slotsDir)
147	
148		// Control: a new seq for the same long node genuinely needs a slot write.
149		out, errOut, code := runCLI(t, dir, longIDJSON(longNode, 2, 12350, 0, "1.26.0", "2026-10-01T11:59:30Z"),
150			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
151		if code == 0 {
152			t.Fatalf("control: a needed slot write must fail with slots/ read-only; stdout=%q", out)
153		}
154		if !strings.Contains(errOut, "failed to persist heartbeat batch") {
155			t.Fatalf("control failure should be a persistence error, got stderr=%q", errOut)
156		}
157	
158		// Duplicate retransmit: same record (emoji-free id here, literal spelling).
159		out, errOut, code = runCLI(t, dir, longIDJSON(longNode, 1, 12345, 0, "1.26.0", "2026-10-01T11:59:00Z"),
160			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
161		if code != 0 {
162			t.Fatalf("duplicate-only long-id submit must succeed without a rewrite: exit=%d stderr=%q", code, errOut)
163		}
164		if strings.TrimRight(out, "\n") != "submitted: new=0 duplicate=1" {
165			t.Errorf("stdout=%q, want new=0 duplicate=1", out)
166		}
167		assertNoTempFiles(t, slotsDir)
168	
169		if err := os.Chmod(slotsDir, 0o755); err != nil {
170			t.Fatal(err)
171		}
172		afterBytes, err := os.ReadFile(slotPath)
173		if err != nil {
174			t.Fatal(err)
175		}
176		if string(afterBytes) != string(beforeBytes) {
177			t.Errorf("the long id's slot was rewritten despite an all-duplicate batch")
178		}
179		lines := historyLines(t, dir, longNode)
180		if len(lines) != 1 || !strings.Contains(lines[0], "seq=1") || strings.Contains(lines[0], "seq=2") {
181			t.Errorf("long-id history must keep only seq 1, got %q", lines)
182		}
183	}
184	
185	// TestCLIMixedBatchDuplicateOnlyNodeFaultDoesNotBlockOtherNode covers the two
186	// cross-layout combinations: the duplicate-only node's storage directory is
187	// unable to rewrite, while another node in the SAME batch reports a genuine
188	// new record in the other (writable) directory. The dup-only node must not be
189	// written and must not drag the legal submit down; counts, history and file
190	// bytes are all checked afterwards.
191	func TestCLIMixedBatchDuplicateOnlyNodeFaultDoesNotBlockOtherNode(t *testing.T) {
192		// "new-long-node-" is 14 bytes; 10 repeats = 140 bytes -> slots/.
193		longNew := strings.Repeat("new-long-node-", 10)
194	
195		cases := []struct {
196			name     string
197			setup    func(dir string)        // pre-saved history
198			faultDir func(dir string) string // directory made read-only
199			batch    string                  // mixed batch JSON
200			dupNode  string
201			newNode  string
202			wantLine string
203		}{
204			{
205				name: "duplicate short node blocked, new long node must still save",
206				setup: func(dir string) {
207					submitBatch(t, dir, `[{"node":"dup","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":12345,"missed":0}]`)
208				},
209				faultDir: func(dir string) string { return filepath.Join(dir, "nodes") },
210				batch: `[
211				  {"node":"dup","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":12345,"missed":0},
212				  {"node":"` + longNew + `","seq":1,"collected_at":"2026-10-01T11:59:30Z","version":"1.0","height":77,"missed":0}
213				]`,
214				dupNode:  "dup",
215				newNode:  longNew,
216				wantLine: "height=77 missed=0",
217			},
218			{
219				name: "duplicate long node blocked, new short node must still save",
220				setup: func(dir string) {
221					submitBatch(t, dir, longIDJSON(longDupNode(), 1, 12345, 0, "1.26.0", "2026-10-01T11:59:00Z"))
222				},
223				faultDir: func(dir string) string { return filepath.Join(dir, "slots") },
224				batch: `[` +
225					stripOuterBrackets(longIDJSON(longDupNode(), 1, 12345, 0, "1.26.0", "2026-10-01T11:59:00Z")) + `,
226				  {"node":"newshort","seq":1,"collected_at":"2026-10-01T11:59:30Z","version":"1.0","height":88,"missed":0}
227				]`,
228				dupNode:  longDupNode(),
229				newNode:  "newshort",
230				wantLine: "height=88 missed=0",
231			},
232		}
233		for _, tc := range cases {
234			t.Run(tc.name, func(t *testing.T) {
235				dir := t.TempDir()
236				tc.setup(dir)
237				dupBefore, err := os.ReadFile(nodeFileHexPath(dir, tc.dupNode))
238				if err != nil {
239					t.Fatal(err)
240				}
241				faultDir := tc.faultDir(dir)
242				readonlyDir(t, faultDir)
243	
244				out, errOut, code := runCLI(t, dir, tc.batch,
245					"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
246				if code != 0 {
247					t.Fatalf("the dup-only node must not block the other node's legal submit: exit=%d stderr=%q", code, errOut)
248				}
249				if strings.TrimRight(out, "\n") != "submitted: new=1 duplicate=1" {
250					t.Errorf("stdout=%q, want new=1 duplicate=1", out)
251				}
252				assertNoTempFiles(t, faultDir)
253	
254				// Restore so snapshot reads/cleanup behave normally.
255				if err := os.Chmod(faultDir, 0o755); err != nil {
256					t.Fatal(err)
257				}
258				dupAfter, err := os.ReadFile(nodeFileHexPath(dir, tc.dupNode))
259				if err != nil {
260					t.Fatal(err)
261				}
262				if string(dupAfter) != string(dupBefore) {
263					t.Errorf("duplicate-only node file was rewritten by the mixed batch")
264				}
265				newLines := historyLines(t, dir, tc.newNode)
266				if len(newLines) != 1 || !strings.Contains(newLines[0], "seq=1") ||
267					!strings.Contains(newLines[0], tc.wantLine) {
268					t.Errorf("the other node's new heartbeat must be queryable, got %q", newLines)
269				}
270				dupLines := historyLines(t, dir, tc.dupNode)
271				if len(dupLines) != 1 || !strings.Contains(dupLines[0], "seq=1") {
272					t.Errorf("dup-only node history must stay exactly as it was, got %q", dupLines)
273				}
274			})
275		}
276	}
277	
278	// longDupNode returns a node id long enough to use the slots/ layout
279	// ("dup-long-node-" is 14 bytes; 11 repeats = 154 bytes).
280	func longDupNode() string {
281		return strings.Repeat("dup-long-node-", 11)
282	}
283	
284	// stripOuterBrackets turns a single-element JSON array into its object text,
285	// so a caller can embed it inside a larger hand-written array.
286	func stripOuterBrackets(arrayJSON string) string {
287		s := strings.TrimSpace(arrayJSON)
288		s = strings.TrimPrefix(s, "[")
289		s = strings.TrimSuffix(s, "]")
290		return strings.TrimSpace(s)
291	}
292	
293	// TestCLIDuplicateEquivalentSpellingsDoNotRewrite pins the observable
294	// identity rule at the command boundary: same instant in another timezone and
295	// node/version written with equivalent JSON \uXXXX escapes all repeat an
296	// already-saved record; each input occurrence counts as a duplicate, the file
297	// is byte-identical and the history keeps the original text and instant.
298	func TestCLIDuplicateEquivalentSpellingsDoNotRewrite(t *testing.T) {
299		dir := t.TempDir()
300		submitBatch(t, dir, `[{"node":"peer-a","seq":7,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":12345,"missed":0}]`)
301		before := readNodeFile(t, dir, "peer-a")
302	
303		bs := "\\"
304		batch := `[
305		  {"node":"peer-a","seq":7,"collected_at":"2026-10-01T19:59:00+08:00","version":"1.0","height":12345,"missed":0},
306		  {"node":"` + bs + `u0070eer-` + bs + `u0061","seq":7,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":12345,"missed":0},
307		  {"node":"peer-a","seq":7,"collected_at":"2026-10-01T11:59:00Z","version":"` + bs + `u0031.` + bs + `u0030","height":12345,"missed":0}
308		]`
309		out, errOut, code := submit(t, dir, batch)
310		if code != 0 {
311			t.Fatalf("equivalent spellings must submit as duplicates: exit=%d stderr=%q", code, errOut)
312		}
313		if strings.TrimRight(out, "\n") != "submitted: new=0 duplicate=3" {
314			t.Errorf("stdout=%q, want new=0 duplicate=3", out)
315		}
316	
317		if got := readNodeFile(t, dir, "peer-a"); got != before {
318			t.Errorf("the node file was rewritten with an equivalent spelling:\nbefore=%q\nafter =%q", before, got)
319		}
320		lines := historyLines(t, dir, "peer-a")
321		if len(lines) != 1 {
322			t.Fatalf("history must keep exactly one row, got %q", lines)
323		}
324		want := "node=peer-a seq=7 collected_at=2026-10-01T11:59:00Z version=1.0 height=12345 missed=0"
325		if lines[0] != want {
326			t.Errorf("original text/collected instant was rewritten:\n got %q\nwant %q", lines[0], want)
327		}
328	}
