	}

	// Same instant expressed in a different timezone is still a duplicate.
	rebased := []Heartbeat{hb("n1", 1, receive.Add(-2*time.Minute).In(time.FixedZone("+08", 8*3600)), "1.0", 100, 0)}
	newC, dupC, err = store.Submit(rebased, receive)
